   j = sp->j;
   peakX2 = sp->peakX2;
   peakY2 = sp->peakY2;
   shiftX = sp->shiftX;
   shiftY = sp->shiftY;
   sumX = sp->sumX;
   sumX2 = sp->sumX2;
   sumXY = sp->sumXY;
   sumY = sp->sumY;
   sumY2 = sp->sumY2;
   x_inReal0 = sp->x_inReal0;
   x_inReal1 = sp->x_inReal1;
   pkSlot0 = sp->today & sp->xMask;
   pkVal0 = inReal0;
   pkSlot1 = sp->today & sp->xMask;
   pkVal1 = inReal1;
